message.content:
{
  "description": "The creature is a quadrupedal animal shown in profile facing right, standing on sparse grass and dirt. It has a large, domed tortoise-like shell covering its back and sides with brown and cream patterned scutes, and a thick, shaggy pale tan fur covering its neck, head-top, chest, and legs. Its head is reptilian and scaly with a beaked mouth and a dark eye, emerging from a voluminous furry mane around the neck. Its four thick legs end in broad clawed feet, and a small pointed scaly tail protrudes from under the rear of the shell. The overall appearance combines reptilian shell and skin with mammalian fur.",
  "parts": [
    {
      "part": "head",
      "looks_like": "scaly reptilian head with polygonal scales, a dark eye with surrounding scales, a blunt beaked snout and a slightly open mouth showing the lower jaw, protruding forward from the furry neck at the front of the body"
    ,
      "where": "at the front end of the body, extending from the mane"
    },
    {
      "part": "mane",
      "looks_like": "dense, long, shaggy pale tan to cream fur that is tousled and layered, forming a thick ruff around the neck and chest and a tuft on top of the head",
      "where": "encircling the neck, covering the top of the head, hanging down the front of the chest and along the sides of the neck"
    },
    {
      "part": "legs",
      "looks_like": "four thick columnar legs, covered with long pale fur on the sides and rear and with rows of large pointed overlapping scales on the front surfaces, with wrinkled skin visible at the joints near the shell",
      "where": "underneath the shell, two forelegs at the front and two hind legs at the rear, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "broad rounded feet with pebbly scaly skin on the soles and tops, each bearing three large dark blunt claws protruding forward",
      "where": "at the bottom end of each leg in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "short, narrow, pointed tail covered in small scales, tapering to a tip, with long fur surrounding its base on the hindquarters",
      "where": "at the rear of the body protruding from beneath the back edge of the shell on the left side of the image"
    },
    {
      "part": "shell",
      "looks_like": "large domed carapace made of polygonal scutes with radiating brown and cream striped patterns, a slightly raised central keel, a flared serrated edge at the rear, and a pale plastron visible along the lower side",
      "where": "covering the back and sides of the torso from behind the neck to above the hind legs"
    },
    {
      "part": "scales",
      "looks_like": "small polygonal scales on the head and on the feet, and larger pointed keeled scales arranged in overlapping rows on the front of the forelegs",
      "where": "on the head, on the dorsal front of the forelegs, and on the feet"
    },
    {
      "part": "plates",
      "looks_like": "hard polygonal scutes with concentric growth lines forming the shell, each with a raised center",
      "where": "forming the entire outer surface of the shell on the back"
    },
    {
      "part": "markings",
      "looks_like": "alternating dark brown and off-white to cream streaks radiating from the center of each scute, creating a banded mottled pattern",
      "where": "on each scute of the carapace"
    }
  ],
  "attached_objects": [],
  "animals": [
    "tortoise",
    "lion"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
